explicit_checks.pathsafe/paths.py:
DEPOT = "depot"


def resolve(name: str) -> str:
    if name.startswith("/"):
        raise ValueError("absolute names are not allowed")
    if ".." in name.split("/"):
        raise ValueError("names may not escape the depot")
    return f"{DEPOT}/{name}"

single_guard.pathsafe/paths.py:
DEPOT = "depot"


def _is_refused(name: str) -> bool:
    return name.startswith("/") or ".." in name.split("/")


def resolve(name: str) -> str:
    if _is_refused(name):
        raise ValueError(f"refused: {name}")
    return f"{DEPOT}/{name}"

